('Các trường hợp đưa máy biến áp ra khỏi vận hành.', '["- Khi hệ thống rơ le bảo vệ máy biến áp bị hư hỏng.\n - Có tiếng kêu lạ, rung động bất thường.", "Nhiệt độ cuộn dây tăng lên bất thường và liên tục trong điều kiện bình thường, phụ tải không quá định mức.", "Các sứ bị rạn, vỡ, bị phóng điện bề mặt. Đầu cose bị nóng, đỏ.", "Cả 3 đáp án đều đúng"]', 3, 'Hệ thống trung thế'),
('Khi máy biến áp bị quá tải hoặc bất thường, phải kiểm tra các hạng mục sau.', '["Kiểm tra dòng điện và điện áp các pha", "- Kiểm tra nhiệt độ cuộn dây \n - Kiểm tra tình trạng làm việc của các bộ làm mát", "- Kiểm tra tiếng kêu, tiếng động của biến áp\n - Kiểm tra tình trạng làm việc của hệ thống rơ le bảo vệ", "Cả 3 đáp án đều đúng"]', 3, 'Hệ thống trung thế'),
('Quy định đưa máy cắt ra vị trí thử nghiệm.', '["Xác nhận máy cắt đã ở trạng thái mở", "Xác nhận khóa lock thao tác ở vị trí nằm ngang", "- Dùng cần thao tác chuyên dụng tra vào lỗ thao tác và quay ngược chiều kim đồng hồ để đưa máy cắt ra vị trí Test\n - Kiểm tra và xác nhận máy cắt đã ở vị trí Test", "Cả 3 đáp án đều đúng"]', 3, 'Hệ thống trung thế'),
('Quy định đóng dao đất các lộ ra.', '["- Xác nhận máy cắt đã ở vị trí Test.\n- Xác nhận máy cắt ở trạng thái OFF", "- Đưa cần dao đất vào lỗ thao tác theo phương thẳng đứng", "- Xoay cần thao tác dao đất cùng chiều kim đồng hồ một góc khoảng 95 độ\n - Kiểm tra bộ chỉ thị dao đất đã đóng, và rút cần thao tác", "Cả 3 đáp án đều đúng"]', 3, 'Hệ thống trung thế'),
('Quy định mở dao đất các lộ ra.', '["Đưa cần thao tác dao đất vào lỗ thao tác theo phương ngang.", "Xoay cần thao tác ngược chiều kim đồng hồ một góc khoảng 95 độ", "Kiêm tra bộ chỉ thị dao đất ở vị trí mở, và rút cần thao tác.", "Cả 3 đáp án đều đúng"]', 3, 'Hệ thống trung thế'),
('Quy định vận hành dao đất thanh cái 412-14.', '["Đảm bảo toàn bộ máy cắt kết giàn với thanh cái C42 đều nằm ở vị trí “thí nghiệm”", "Rút chìa khoá “BB1” ở mỗi máy cắt cắm vào dãy EC1 khoang “TUC41” để giải lock và rút chìa “EC1” cắm vào khoang dao đất “412-24” để giải lock.", "Tiếp tục thực hiện đóng/mở như quy định đóng/mở dao đất các lộ ra.", "Cả 3 đáp án đều đúng"]', 3, 'Hệ thống trung thế'),
('Quy định vận hành dao đất thanh cái TUC41-14', '["Đảm bảo toàn bộ máy cắt kết giàn với thanh cái C41 đều nằm ở vị trí “thí nghiệm”", "Rút chìa khoá “BB1” ở mỗi máy cắt cắm vào khoang “TUC41” để rút chìa “EC2” cắm vào khoang dao đất “TUC41-14” để giải lock.", "Tiếp tục thực hiện đóng/mở như quy định đóng/mở dao đất các lộ ra.", "Cả 3 đáp án đều đúng"]', 3, 'Hệ thống trung thế'),
